<script setup>
import { computed, ref } from 'vue'
import { availableSamples, sampleById } from '../../world/laboratory/SampleCatalog.js'
import { EVIDENCE, LAB_SOURCES } from '../../world/laboratory/ScientificProvenance.js'
import { elementalContributions } from '../../world/laboratory/OxygenExperiment.js'
import SampleViewer from './SampleViewer.vue'
import ExperimentPanel from './ExperimentPanel.vue'
const props=defineProps({system:Object,eclss:Object,sampleStatus:String,initialTab:String})
const emit=defineEmits(['close','action'])
const tab=ref(props.initialTab??'catalog')
const sample=computed(()=>sampleById(props.system.selectedId))
const record=computed(()=>props.system.records[sample.value.id])
const elements=computed(()=>elementalContributions(sample.value))
const tabs=[['catalog','Muestras'],['register','Registro'],['visual','Inspección'],['microscopy','Microscopio'],['elemental','Análisis'],['mineralogy','Minerales'],['life','Soporte vital'],['energy','Energía'],['shielding','Blindaje'],['journal','Bitácora']]
function act(action,payload){emit('action',{action,payload})}
function select(id){act('select',{id});tab.value='register'}
</script>
<template>
  <div class="resource-backdrop" @click.self="emit('close')">
    <section class="resource-panel" role="dialog" aria-modal="true" aria-labelledby="resource-title" @keydown.esc.stop="emit('close')">
      <header><div><small>KYNEX · INVESTIGACIÓN LUNAR</small><h2 id="resource-title">RESOURCE LAB 01</h2></div><button class="resource-close" aria-label="Cerrar laboratorio" @click="emit('close')">×</button></header>
      <nav aria-label="Instrumentos e investigaciones"><button v-for="[id,label] in tabs" :key="id" :class="{selected:tab===id}" :aria-pressed="tab===id" @click="tab=id">{{ label }}</button></nav>
      <div class="resource-selection"><label>Muestra<select :value="sample.id" @change="select($event.target.value)"><option v-for="item in availableSamples(sampleStatus)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><span class="resource-evidence">{{ EVIDENCE[sample.evidence] }}</span></div>
      <main class="resource-content">
        <template v-if="tab==='catalog'"><h3>¿Qué material quieres investigar?</h3><p>Las referencias Apollo vienen de colecciones documentadas. Tu roca virtual se incorpora al entregarla en la mesa del hábitat.</p><div class="resource-catalog"><button v-for="item in availableSamples(sampleStatus)" :key="item.id" @click="select(item.id)"><small>{{ item.evidence }} · {{ item.id }}</small><b>{{ item.name }}</b><span>{{ item.type }}</span></button></div><p class="resource-warning">LOLA proporciona topografía. Los mapas espectrales orbitales dan contexto regional; ninguno identifica automáticamente una roca pequeña de Site04.</p><a :href="LAB_SOURCES.m3.url" target="_blank" rel="noreferrer">Archivo M³ y sus productos espectrales ↗</a></template>
        <template v-else-if="tab==='register'"><h3>{{ sample.name }}</h3><dl><dt>Identificador original</dt><dd>{{ sample.id }}</dd><dt>Misión y origen</dt><dd>{{ sample.mission }}</dd><dt>Clasificación</dt><dd>{{ sample.type }}</dd><dt>Procedencia</dt><dd>{{ sample.registeredOrigin }}</dd><dt>Estado</dt><dd>{{ record?'REGISTRADA':'PENDIENTE DE REGISTRO' }}</dd></dl><button @click="act('register')" :disabled="!!record">{{ record?'REGISTRO CONSERVADO':'REGISTRAR MUESTRA' }}</button><button v-if="record" @click="tab='visual'">INSPECCIONAR →</button></template>
        <template v-else-if="tab==='visual'||tab==='microscopy'"><h3>{{ tab==='visual'?'Inspección visual':'Microscopio virtual' }}</h3><SampleViewer :sample="sample" :microscopy="tab==='microscopy'" /><button :disabled="!record" @click="act(tab)">{{ record?.[tab]?'OBSERVACIÓN REGISTRADA':'REGISTRAR OBSERVACIÓN' }}</button><p v-if="!record">Primero registra la muestra.</p></template>
        <template v-else-if="tab==='elemental'"><h3>Consulta de análisis documentado</h3><p>Este terminal consulta resultados publicados; no realiza un ensayo físico de la roca a distancia.</p><button :disabled="!record" @click="act('elemental')">CONSULTAR RESULTADOS</button><template v-if="record?.elemental"><p>{{ sample.chemistryMethod }}</p><div v-if="sample.chemistry.length" class="resource-table-scroll"><table><caption>OBSERVED · {{ sample.id }} · % masa de óxido, sin normalizar</caption><thead><tr><th>Óxido</th><th>Valor</th><th>± publicado</th></tr></thead><tbody><tr v-for="row in sample.chemistry" :key="row.oxide"><th>{{ row.oxide }}</th><td>{{ row.value }}</td><td>{{ row.uncertainty }}</td></tr></tbody></table><details><summary>DERIVED · aportes elementales calculados</summary><p>Conversión estequiométrica de los óxidos listados. No son mediciones elementales independientes ni prueba de fases minerales.</p><table><tbody><tr v-for="element in elements" :key="element.element"><th>{{ element.element }}</th><td>{{ element.value.toFixed(3) }} % masa</td></tr></tbody></table></details></div><p v-else class="resource-warning">UNAVAILABLE · Dato cuantitativo no disponible en esta versión del catálogo.</p></template></template>
        <template v-else-if="tab==='mineralogy'"><h3>Minerales documentados</h3><button :disabled="!record" @click="act('mineralogy')">CONSULTAR ESTUDIOS</button><template v-if="record?.mineralogy"><ul v-if="sample.minerals.length"><li v-for="mineral in sample.minerals" :key="mineral">{{ mineral }}</li></ul><p>{{ sample.mineralNote }}</p><p class="resource-small">La composición en óxidos no demuestra por sí sola qué minerales están presentes: se necesitan estudios mineralógicos.</p></template></template>
        <ExperimentPanel v-else-if="['life','energy','shielding'].includes(tab)" :area="tab" :sample="sample" :record="record" :system="system" :eclss="eclss" @action="emit('action',$event)" />
        <template v-else-if="tab==='journal'"><h3>Bitácora de recursos · {{ system.journal.length }} conclusiones</h3><p v-if="!system.journal.length">Todavía no hay conclusiones. Registra una muestra, obsérvala y estudia una de las tres aplicaciones.</p><article v-for="entry in system.journal" :key="entry.sampleId+entry.area" class="resource-result"><small>{{ entry.evidence }} · {{ entry.sampleId }} · {{ {life:'SOPORTE VITAL',energy:'ENERGÍA',shielding:'BLINDAJE'}[entry.area] }}</small><h4>{{ entry.conclusion }}</h4><p>Consultas: {{ entry.observed.visual?'visual':'' }} · {{ entry.observed.microscopy?'microscopio':'' }} · {{ entry.observed.chemistry.length }} óxidos documentados · {{ entry.observed.minerals.length }} entradas mineralógicas.</p><p v-for="r in entry.results" :key="r.id">{{ r.kind==='shielding'?'DERIVED · Cobertura '+r.arealGcm2+' g/cm²; dosis no disponible.':r.status==='completed'?'MODELLED · O₂ potencial '+(r.estimate.estimatedKg*1000).toFixed(2)+' g; consumo '+r.spentKWh.toFixed(3)+' kWh.':'Ensayo cancelado; no se registró producción.' }}</p><ul><li v-for="limit in entry.limitations" :key="limit">{{ limit }}</li></ul><a v-for="id in entry.sources" :key="id" :href="LAB_SOURCES[id]?.url" target="_blank" rel="noreferrer">{{ LAB_SOURCES[id]?.title }} ↗</a></article></template>
        <details class="resource-sources"><summary>Procedencia y referencias de esta muestra</summary><p>{{ EVIDENCE[sample.evidence] }} · {{ sample.registeredOrigin }}</p><a v-for="id in sample.sources" :key="id" :href="LAB_SOURCES[id].url" target="_blank" rel="noreferrer">{{ LAB_SOURCES[id].title }} ↗</a><p>OBSERVED: publicado para una muestra. DERIVED: calculado. MODELLED: predicción. SCENARIO: supuesto educativo. UNAVAILABLE: dato no incorporado o inexistente para este objeto.</p></details>
      </main>
      <footer><p role="status">{{ system.message }}</p><button @click="emit('close')">VOLVER A EXPLORAR</button></footer>
    </section>
  </div>
</template>
<style>
.resource-backdrop{position:fixed;inset:0;z-index:40;display:grid;place-items:center;background:#02080b45;padding:18px;backdrop-filter:blur(3px)}
.resource-panel{width:min(970px,100%);height:min(860px,94vh);display:flex;flex-direction:column;min-height:0;border:1px solid #a8e9d079;border-radius:22px;background:linear-gradient(140deg,#143b3bd9,#06151de8);box-shadow:0 25px 90px #0009;backdrop-filter:blur(28px) saturate(135%);color:#e3f4eb;font:13px/1.6 'DM Sans',sans-serif;overflow:hidden}
.resource-panel header{padding:20px 24px 12px;display:flex;align-items:center;justify-content:space-between;gap:12px}.resource-panel h2{font:600 26px 'Space Grotesk',sans-serif;margin:3px 0}.resource-panel small{font:10px/1.4 'DM Mono',monospace;color:#b4dacb}.resource-panel button,.resource-panel select{font:11px/1.4 'DM Mono',monospace;border:1px solid #b4e7cf6a;color:#e4f6ed;background:#73c5a416;border-radius:8px;padding:10px 12px;cursor:pointer}.resource-panel button:hover{background:#b2ffda26}.resource-panel button:disabled{opacity:.45;cursor:default}.resource-panel button:focus-visible,.resource-panel select:focus-visible{outline:2px solid #ffda9a;outline-offset:3px}.resource-panel .resource-close{font-size:25px;border-radius:50%;width:40px;height:40px;padding:0}.resource-panel nav{display:flex;gap:6px;overflow:auto;padding:0 24px 12px;flex-shrink:0}.resource-panel nav button{white-space:nowrap}.resource-panel .selected{background:#b1e4cc;color:#081c1b}.resource-selection{padding:10px 24px;display:flex;align-items:end;justify-content:space-between;gap:14px;border-block:1px solid #c5ead52b;background:#0002}.resource-selection label{flex:1;margin:0}.resource-panel label{display:grid;gap:6px;margin:16px 0}.resource-selection label{margin:0}.resource-panel select{width:100%;background:#112d30}.resource-content{min-height:0;flex:1;overflow:auto;padding:10px 24px 24px;scrollbar-color:#8fcab8 #123033}.resource-content h3{font:600 23px 'DM Sans',sans-serif;margin:12px 0}.resource-content a{color:#b2e4d1;display:block;font-size:11px;margin:10px 0;text-decoration:underline}.resource-content details{border:1px solid #b7e7d133;border-radius:10px;padding:12px;margin:12px 0}.resource-content summary{cursor:pointer}.resource-content input[type=range]{width:100%;accent-color:#a7e9c7}.resource-evidence{font:10px/1.5 'DM Mono',monospace;color:#dbbf83;letter-spacing:.04em}.resource-catalog{display:grid;grid-template-columns:1fr 1fr;gap:10px}.resource-catalog button{display:grid;gap:8px;text-align:left;padding:16px}.resource-catalog b{font-size:16px}.resource-catalog span{color:#abc8bc}.resource-warning{border-left:2px solid #dfbb79;background:#cb8b2520;padding:12px;font-size:12px}.resource-small{color:#b1cbbf;font-size:11px}.resource-meters{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:16px 0}.resource-meters>div{display:grid;gap:5px;border:1px solid #a5d9bf3a;border-radius:10px;padding:12px;background:#ffffff08}.resource-meters b{font:600 23px 'DM Sans',sans-serif}.resource-job{display:grid;gap:10px;padding:15px;border:1px solid #e4c78b77;border-radius:12px;margin:16px 0}.resource-job progress{width:100%;accent-color:#a7dfbf}.resource-result{padding:15px;border:1px solid #a4d7bf50;border-radius:12px;background:#ffffff09;margin:14px 0}.resource-conclusion{display:grid;gap:8px;border-top:1px solid #b9e3cc3d;margin-top:22px;padding-top:18px}.resource-panel table{border-collapse:collapse;width:100%;font:12px 'DM Mono',monospace;margin:16px 0}.resource-panel th,.resource-panel td{padding:9px;border-bottom:1px solid #b5dac434;text-align:left}.resource-panel caption{text-align:left;margin-bottom:12px;color:#c9c39b}.resource-table-scroll{overflow-x:auto}.resource-panel dl{display:grid;grid-template-columns:155px 1fr;gap:12px}.resource-panel dt{color:#a4c9b9}.resource-panel dd{margin:0}.resource-panel footer{border-top:1px solid #c2e9d334;padding:12px 24px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-shrink:0;background:#06151b66}.resource-panel footer p{font-size:11px;margin:0;max-width:70%;color:#cfdfb8}.resource-viewer .lunar-rock-viewer{height:230px}.resource-viewer p{font-size:12px}.resource-panel footer button{white-space:nowrap}
@media(max-width:650px){.resource-backdrop{padding:7px}.resource-panel{height:96vh;border-radius:14px}.resource-panel header,.resource-panel footer,.resource-content,.resource-selection{padding:12px}.resource-panel nav{padding:0 12px 10px}.resource-selection{display:block}.resource-selection>span{display:block;margin-top:7px}.resource-meters,.resource-catalog{grid-template-columns:1fr}.resource-panel dl{grid-template-columns:1fr;gap:4px}.resource-panel dd{margin-bottom:10px}.resource-panel footer{display:block}.resource-panel footer p{max-width:100%;margin-bottom:8px}}
</style>
